# Official Datenschutzerklärung supplied by the client, 2026-08-22.
#
# The German is the client's own wording, reproduced faithfully. The only
# changes are Swiss orthography (ss for ß, per CLAUDE.md) and Swiss quotation
# marks, neither of which alters meaning. Paragraphs are stored as trusted
# HTML because several contain links; the generator emits them unescaped.
#
# FR, IT and EN are working translations. Legal text is not marketing copy, so
# each non-German page carries a notice naming the German version as
# authoritative. If Deico has official translations, they replace these.
use strict; use warnings; use utf8;
our %T;

my $GA_TERMS   = '<a href="https://policies.google.com/">policies.google.com</a>';
my $GA_SUPPORT = '<a href="https://support.google.com/analytics/answer/12017362">support.google.com/analytics/answer/12017362</a>';
my $GA_OPTOUT  = '<a href="https://tools.google.com/dlpage/gaoptout">tools.google.com/dlpage/gaoptout</a>';
my $G_PRIVACY  = '<a href="https://policies.google.com/privacy">policies.google.com/privacy</a>';
my $G_ADS      = '<a href="https://adssettings.google.com/authenticated">adssettings.google.com/authenticated</a>';

# ------------------------------------------------------------------ DE ------
$T{de}{privacy} = {
  authoritative => undef,
  sections => [
    { h => 'Website-Analyse mit Google Analytics', p => [
      'Diese Website nutzt Google Analytics 4, einen Webanalyse-Dienst der Google LLC, nachdem die Einwilligung des Benutzers eingeholt wurde. Die zuständigen Stellen sind Google Ireland Limited, Google Building Gordon House, 4 Barrow St, Dublin, D04 E5W5, Irland, für Benutzer aus der EU/EWR und der Schweiz. Google Analytics 4 praktiziert standardmässig die IP-Anonymisierung, d.h., deine IP-Adresse wird sofort gekürzt, wenn du mit dieser Website interagierst. Nur in seltenen Fällen wird deine vollständige IP an einen in den USA basierten Google-Server übertragen und dort gekürzt. Google beteuert, dass die über Google Analytics übertragene IP niemals mit anderen Google-Daten kombiniert wird. Google Analytics 4 wird nur mit deiner Zustimmung über das Cookie-Banner aktiviert und kann jederzeit über die Cookie-Einstellungen rückgängig gemacht werden.',
      'Die verarbeiteten Daten umfassen: Nutzungsdaten wie Seitenaufrufe, Website-Interaktion, allgemeiner Standort und Besuchsdauer; und Kommunikationsdaten wie gekürzte IP-Adressen, User-Agent, Spracheinstellungen und Bildschirmauflösung. Der Zweck dieser Datenverarbeitung besteht darin, dass Google in Ihrem Namen die Nutzung Ihrer Website auswertet, Berichte über die Aktivitäten zusammenstellt und die Leistung der Website analysiert. Diese Datenverarbeitung ist legal, basierend auf deiner Zustimmung gemäss Art. 6 Abs. 1 S. 1 lit. a DSGVO und § 25 Abs. 1 S. 1 TDDDG.',
      'Google Ireland Limited, Google LLC und Alphabet Inc sind die Empfänger dieser Daten. Deine Website-Nutzungsinformationen werden in der Regel an einen Google-Server in den USA gesendet, eine Aktion, die durch den jüngsten Angemessenheitsbeschluss der Europäischen Kommission vom 10. Juli 2023 legitimiert wurde, der die Zertifizierung von Google LLC unter dem EU-US-Datenschutzschild anerkennt. In Bezug auf die Datenspeicherung wird jede Daten, die mit Cookies verknüpft sind, automatisch nach einer bestimmten Zeit gelöscht, monatlich für Daten, die ihre Aufbewahrungsfrist erreicht haben, und maximal 2 Jahre für Google Analytics-Cookies.',
      "Für weitere Informationen zu den Nutzungsbedingungen von Google Analytics und zur Datenschutzrichtlinie von Google, besuchen Sie bitte $GA_TERMS und $GA_SUPPORT.",
      'Google Analytics verwendet sog. «Cookies», Textdateien, die auf dem Computer des Seitenbesuchers gespeichert werden und die eine Analyse der Benutzung der Website durch den Seitenbesucher ermöglichen. Die durch das Cookie erzeugten Informationen über die Benutzung dieser Website durch den Seitenbesucher (einschliesslich der gekürzten IP-Adresse) werden in der Regel an einen Server von Google übertragen und dort gespeichert.',
      'Google Analytics wird ausschliesslich mit der Erweiterung «_anonymizeIp()» auf dieser Website verwendet. Diese Erweiterung stellt eine Anonymisierung der IP-Adresse durch Kürzung sicher und schliesst eine direkte Personenbeziehbarkeit aus. Durch die Erweiterung wird die IP-Adresse von Google innerhalb von Mitgliedstaaten der Europäischen Union oder in anderen Vertragsstaaten des Abkommens über den Europäischen Wirtschaftsraum zuvor gekürzt. Nur in Ausnahmefällen wird die volle IP-Adresse an einen Server von Google in den USA übertragen und dort gekürzt. Die im Rahmen von Google Analytics von dem entsprechenden Browser übermittelte IP-Adresse wird nicht mit anderen Daten von Google zusammengeführt.',
      'Im Auftrag des Seitenbetreibers wird Google die anfallenden Informationen benutzen, um die Nutzung der Website auszuwerten, um Reports über die Websiteaktivitäten zusammenzustellen und um weitere mit der Websitenutzung und der Internetnutzung verbundene Dienstleistungen dem Seitenbetreiber gegenüber zu erbringen (Art. 6 Abs. 1 lit. f DSGVO). Das berechtigte Interesse an der Datenverarbeitung liegt in der Optimierung dieser Website, der Analyse der Benutzung der Website und der Anpassung der Inhalte. Die Interessen der Nutzer werden durch die Pseudonymisierung hinreichend gewahrt.',
      'Google LLC. ist nach dem sog. Privacy Shield zertifiziert (Listeneintrag hier) und gewährleistet auf dieser Basis ein angemessenes Datenschutzniveau. Die gesendeten und mit Cookies, Nutzerkennungen (z. B. User-ID) oder Werbe-IDs verknüpften Daten werden nach 50 Monaten automatisch gelöscht. Die Löschung von Daten, deren Aufbewahrungsdauer erreicht ist, erfolgt automatisch einmal im Monat.',
      "Die Erfassung durch Google Analytics kann verhindert werden, indem der Seitenbesucher die Cookie-Einstellungen für diese Website anpasst. Der Erfassung und Speicherung der IP-Adresse und der durch Cookies erzeugten Daten kann ausserdem jederzeit mit Wirkung für die Zukunft widersprochen werden. Das entsprechende Browser-Plugin kann unter dem folgenden Link heruntergeladen und installiert werden: $GA_OPTOUT.",
      'Der Seitenbesucher kann die Erfassung durch Google Analytics auf dieser Webseite verhindern, indem er auf folgenden Link klickt. Es wird ein Opt-Out-Cookie gesetzt, der die zukünftige Erfassung der Daten beim Besuch dieser Website verhindert.',
      "Weitere Informationen zur Datennutzung durch Google, Einstellungs- und Widerspruchsmöglichkeiten, finden sich in der Datenschutzerklärung von Google ($G_PRIVACY) sowie in den Einstellungen für die Darstellung von Werbeeinblendungen durch Google ($G_ADS).",
    ]},
    { h => 'Spamschutz mit Google reCAPTCHA', p => [
      "Wir haben Google reCAPTCHA in Formularen auf unserer Webseite implementiert, um zu überprüfen, ob die in den Formularen eingegebenen Daten von menschlichen Besuchern stammen oder von Maschinen oder automatisierten Programmen, die auch als «Bots» bekannt sind. Dieses Tool analysiert automatisch das Verhalten der Webseitenbesucher, sobald sie mit der Webseite interagieren, unter Verwendung verschiedener Informationen wie IP-Adresse, Aufenthaltsdauer und Mausbewegungen. Die verarbeiteten Daten umfassen Nutzungsdaten wie die aufgerufene Webseite, Datum und Uhrzeit des Zugriffs und Mausbewegungen sowie Kommunikationsdaten wie IP-Adressen, Browsertyp und Betriebssystem. Diese Verarbeitung richtet sich an Webseitenbesucher und Nutzer von Online-Diensten. Der Hauptzweck dieser Verarbeitung besteht darin, den Missbrauch unseres Kontaktformulars zu verhindern und dadurch die Sicherheit zu erhöhen. Die rechtliche Grundlage dafür ist unser berechtigtes Interesse gemäss Art. 6 Abs. 1 S. 1 lit. f. DSGVO. Die Datenempfänger sind Google Ireland Ltd, ansässig in Google Building Gordon House, Barrow St, Dublin 4, Irland, ($G_PRIVACY) und unser Webseiten-Hosting-Anbieter. Während Ihre persönlichen Daten innerhalb der EU verarbeitet werden, wird die Aufbewahrungsfrist für die verarbeiteten Daten von Google Ireland Limited bestimmt. Weitere Informationen finden Sie in der Datenschutzerklärung von Google reCAPTCHA: $G_PRIVACY",
    ]},
    { h => 'Webseitenanalyse (Creator Statistiken)', p => [
      'Wenn du unsere Website besuchst, sammeln wir Informationen über deine Nutzung durch ein Webanalyse-Tool, das von unserem Hosting-Service bereitgestellt wird. Dieses Tool sammelt und kombiniert deine IP-Adresse und deinen User Agent, verkürzt sie und speichert diese Daten mit einer Hash-Funktion. Durch diesen Vorgang wird eine Besucherkennung erstellt, die mit einem zufällig generierten Wert (SALT) verschlüsselt ist, der sich alle 24 Stunden ändert. Diese Methode stellt sicher, dass deine IP-Adresse nicht aus dem gespeicherten Besucheridentifikator rekonstruiert werden kann, so dass deine Anonymität gewahrt bleibt. Ausserdem führen wir diese Informationen nicht mit anderen Daten zusammen und sie werden nur auf dem Server des Hosting-Anbieters gespeichert.',
      'Wir verarbeiten auch Webanalysedaten, HTTP-Daten und Webanalyseprofildaten. Das von uns verwendete Webanalysetool erstellt und speichert ein Webanalyseprofil, das Details über deine Nutzung der Website enthält, wie z. B. Seitenaufrufe, Besuchshäufigkeit, Verweildauer auf jeder Seite und den User Agent deines Geräts. Dazu gehören Nutzungsdaten (wie besuchte Webseiten und Zugriffszeiten) und Kommunikationsdaten (wie Browsertyp, Betriebssystem und IP-Adressen).',
      'Mit der Verarbeitung dieser Daten wollen wir das Nutzerverhalten in zusammengefasster Form analysieren, um die Darstellung und den Inhalt unserer Website zu verbessern. Die Rechtsgrundlage für diese Verarbeitung ist unser berechtigtes Interesse (Art. 6 Abs. 1 lit. (f) GDPR), insbesondere an der Durchführung von Webmessungen, um unsere Produkte und unsere Website zu verbessern.',
      'Die erhobenen Daten werden mit unserem Website-Hosting-Anbieter geteilt und innerhalb der EU verarbeitet.',
    ]},
  ],
};

# ------------------------------------------------------------------ FR ------
$T{fr}{privacy} = {
  authoritative => 'Cette traduction est fournie à titre informatif. En cas de divergence, la version allemande fait foi.',
  sections => [
    { h => 'Analyse du site avec Google Analytics', p => [
      "Ce site utilise Google Analytics 4, un service d'analyse web de Google LLC, après avoir recueilli le consentement de l'utilisateur. Les responsables sont Google Ireland Limited, Google Building Gordon House, 4 Barrow St, Dublin, D04 E5W5, Irlande, pour les utilisateurs de l'UE/EEE et de la Suisse. Google Analytics 4 pratique par défaut l'anonymisation de l'adresse IP, c'est-à-dire que votre adresse IP est immédiatement tronquée lorsque vous interagissez avec ce site. Ce n'est que dans de rares cas que votre adresse IP complète est transmise à un serveur Google situé aux États-Unis, puis tronquée sur place. Google affirme que l'adresse IP transmise via Google Analytics n'est jamais combinée avec d'autres données Google. Google Analytics 4 n'est activé qu'avec votre accord via la bannière de cookies et peut être désactivé à tout moment via les paramètres de cookies.",
      "Les données traitées comprennent : des données d'utilisation telles que les pages consultées, l'interaction avec le site, la localisation générale et la durée de la visite ; et des données de communication telles que les adresses IP tronquées, l'agent utilisateur, les paramètres de langue et la résolution d'écran. La finalité de ce traitement est que Google évalue en votre nom l'utilisation de votre site, compile des rapports sur les activités et analyse les performances du site. Ce traitement est licite sur la base de votre consentement conformément à l'art. 6 al. 1 phr. 1 let. a RGPD et au § 25 al. 1 phr. 1 TDDDG.",
      "Google Ireland Limited, Google LLC et Alphabet Inc sont les destinataires de ces données. Vos informations d'utilisation du site sont en règle générale envoyées à un serveur Google aux États-Unis, une opération légitimée par la récente décision d'adéquation de la Commission européenne du 10 juillet 2023, qui reconnaît la certification de Google LLC au titre du bouclier de protection des données UE-États-Unis. En ce qui concerne la conservation, toutes les données liées à des cookies sont automatiquement supprimées après un certain délai, mensuellement pour les données ayant atteint leur durée de conservation, et au maximum 2 ans pour les cookies Google Analytics.",
      "Pour plus d'informations sur les conditions d'utilisation de Google Analytics et sur la politique de confidentialité de Google, veuillez consulter $GA_TERMS et $GA_SUPPORT.",
      "Google Analytics utilise des « cookies », des fichiers texte enregistrés sur l'ordinateur du visiteur et permettant une analyse de l'utilisation du site par celui-ci. Les informations générées par le cookie concernant l'utilisation de ce site par le visiteur (y compris l'adresse IP tronquée) sont en règle générale transmises à un serveur de Google et y sont enregistrées.",
      "Google Analytics n'est utilisé sur ce site qu'avec l'extension « _anonymizeIp() ». Cette extension garantit une anonymisation de l'adresse IP par troncature et exclut toute identification directe de la personne. Grâce à cette extension, l'adresse IP est préalablement tronquée par Google au sein des États membres de l'Union européenne ou dans d'autres États parties à l'accord sur l'Espace économique européen. Ce n'est que dans des cas exceptionnels que l'adresse IP complète est transmise à un serveur de Google aux États-Unis et y est tronquée. L'adresse IP transmise par le navigateur concerné dans le cadre de Google Analytics n'est pas rapprochée d'autres données de Google.",
      "Pour le compte de l'exploitant du site, Google utilisera les informations recueillies pour évaluer l'utilisation du site, compiler des rapports sur l'activité du site et fournir à l'exploitant d'autres services liés à l'utilisation du site et d'Internet (art. 6 al. 1 let. f RGPD). L'intérêt légitime au traitement réside dans l'optimisation de ce site, l'analyse de son utilisation et l'adaptation des contenus. Les intérêts des utilisateurs sont suffisamment préservés par la pseudonymisation.",
      "Google LLC. est certifié selon le Privacy Shield (entrée de liste ici) et garantit sur cette base un niveau de protection des données approprié. Les données envoyées et liées à des cookies, à des identifiants d'utilisateur (par ex. User-ID) ou à des identifiants publicitaires sont automatiquement supprimées après 50 mois. La suppression des données ayant atteint leur durée de conservation s'effectue automatiquement une fois par mois.",
      "La collecte par Google Analytics peut être empêchée en adaptant les paramètres de cookies de ce site. Il est en outre possible de s'opposer à tout moment, avec effet pour l'avenir, à la collecte et à l'enregistrement de l'adresse IP et des données générées par les cookies. Le module complémentaire de navigateur correspondant peut être téléchargé et installé via le lien suivant : $GA_OPTOUT.",
      "Le visiteur peut empêcher la collecte par Google Analytics sur ce site en cliquant sur le lien suivant. Un cookie d'exclusion est alors placé, qui empêche la collecte future des données lors de la visite de ce site.",
      "De plus amples informations sur l'utilisation des données par Google ainsi que les possibilités de réglage et d'opposition figurent dans la politique de confidentialité de Google ($G_PRIVACY) et dans les paramètres relatifs à l'affichage de publicités par Google ($G_ADS).",
    ]},
    { h => 'Protection anti-spam avec Google reCAPTCHA', p => [
      "Nous avons mis en place Google reCAPTCHA dans les formulaires de notre site afin de vérifier si les données saisies proviennent de visiteurs humains ou de machines et de programmes automatisés, également appelés « bots ». Cet outil analyse automatiquement le comportement des visiteurs dès qu'ils interagissent avec le site, en utilisant différentes informations telles que l'adresse IP, la durée de présence et les mouvements de la souris. Les données traitées comprennent des données d'utilisation telles que la page consultée, la date et l'heure de l'accès et les mouvements de la souris, ainsi que des données de communication telles que les adresses IP, le type de navigateur et le système d'exploitation. Ce traitement concerne les visiteurs du site et les utilisateurs de services en ligne. La finalité principale est d'empêcher l'utilisation abusive de notre formulaire de contact et d'accroître ainsi la sécurité. La base légale est notre intérêt légitime conformément à l'art. 6 al. 1 phr. 1 let. f RGPD. Les destinataires des données sont Google Ireland Ltd, établie à Google Building Gordon House, Barrow St, Dublin 4, Irlande, ($G_PRIVACY) et notre hébergeur. Vos données personnelles étant traitées au sein de l'UE, la durée de conservation des données traitées est déterminée par Google Ireland Limited. Vous trouverez de plus amples informations dans la politique de confidentialité de Google reCAPTCHA : $G_PRIVACY",
    ]},
    { h => 'Analyse du site (statistiques Creator)', p => [
      "Lorsque vous visitez notre site, nous recueillons des informations sur votre utilisation au moyen d'un outil d'analyse web fourni par notre service d'hébergement. Cet outil collecte et combine votre adresse IP et votre agent utilisateur, les tronque et enregistre ces données au moyen d'une fonction de hachage. Ce procédé crée un identifiant de visiteur chiffré avec une valeur générée aléatoirement (SALT) qui change toutes les 24 heures. Cette méthode garantit que votre adresse IP ne peut pas être reconstituée à partir de l'identifiant de visiteur enregistré, de sorte que votre anonymat est préservé. Nous ne rapprochons pas non plus ces informations d'autres données et elles ne sont enregistrées que sur le serveur de l'hébergeur.",
      "Nous traitons également des données d'analyse web, des données HTTP et des données de profil d'analyse web. L'outil d'analyse que nous utilisons crée et enregistre un profil contenant des détails sur votre utilisation du site, comme les pages consultées, la fréquence des visites, le temps passé sur chaque page et l'agent utilisateur de votre appareil. Cela comprend des données d'utilisation (comme les pages visitées et les heures d'accès) et des données de communication (comme le type de navigateur, le système d'exploitation et les adresses IP).",
      "Par le traitement de ces données, nous souhaitons analyser le comportement des utilisateurs sous forme agrégée afin d'améliorer la présentation et le contenu de notre site. La base légale de ce traitement est notre intérêt légitime (art. 6 al. 1 let. f RGPD), en particulier la réalisation de mesures d'audience destinées à améliorer nos produits et notre site.",
      "Les données collectées sont partagées avec notre hébergeur et traitées au sein de l'UE.",
    ]},
  ],
};

